const el=(tag,text,className)=>{const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(className)node.className=className;return node};
const field=(label,node)=>{const box=el('label',label);box.append(node);return box};
const types={answer:'Sai đáp án',image:'Ảnh mờ / lỗi ảnh',explanation:'Giải thích AI chưa đúng',other:'Vấn đề khác'};
export function setupQuality({base,getToken,getQuestion,onRead=()=>{},getDetails=q=>q.explanationDetails}={}){
 let profileEpoch=0,moderator=false,cacheChecked=new Map();const restrictedDialogs=new Set();
 async function api(path,{method='GET',body,auth=false}={}){
  if(!base)throw Error('Chưa kết nối được máy chủ.');const headers={};if(body)headers['Content-Type']='application/json';if(auth)headers.Authorization='Bearer '+getToken();
  const response=await fetch(new URL(path,base),{method,headers,...(body?{body:JSON.stringify(body)}:{}),credentials:'omit',signal:AbortSignal.timeout(20000)});const data=await response.json();if(!response.ok)throw Error(data.error||'Chưa xử lý được yêu cầu.');return data;
 }
 function dialog(title,restricted=false){const d=el('dialog',undefined,'quality-dialog'),head=el('div',undefined,'modal-heading'),close=el('button','Đóng','secondary');close.type='button';close.onclick=()=>d.close();head.append(el('h2',title),close);d.append(head);document.body.append(d);if(restricted)restrictedDialogs.add(d);d.addEventListener('close',()=>{restrictedDialogs.delete(d);d.remove()},{once:true});return d}
 function openReport(q){
  onRead();const details=getDetails(q),d=dialog('Báo lỗi câu hỏi'),form=el('form'),type=el('select');for(const [id,label]of Object.entries(types)){const o=el('option',label);o.value=id;type.append(o)}
  const message=el('textarea');message.required=true;message.maxLength=2000;message.rows=4;message.placeholder='Mô tả chỗ chưa đúng và cách sửa nếu bạn biết.';
  const notice=el('p','Khi gửi, nội dung câu hỏi, đáp án và giải thích đang xem sẽ được chuyển cho người kiểm duyệt. Không gửi tài khoản hoặc ảnh từ tài liệu riêng.','muted');
  const snapshot={stem:q.stem,options:q.options.map(o=>({id:o.id,text:o.text||details?.options?.find(p=>p.id===o.id)?.text||''})),answer:q.answer||'',explanation:details?.reason||q.explanation||'',slide:q.slide,sharedDeck:q.sharedDeck,sharedIndex:q.sharedIndex,cacheKey:details?.cacheKey};
  const preview=el('details'),summary=el('summary','Nội dung sẽ gửi');preview.append(summary,el('pre',JSON.stringify(snapshot,null,2)));
  const submit=el('button','Gửi báo lỗi');submit.type='submit';const status=el('p');status.setAttribute('role','status');form.append(notice,field('Loại lỗi',type),field('Mô tả',message),preview,submit,status);d.append(form);
  form.onsubmit=async event=>{event.preventDefault();submit.disabled=true;status.textContent='Đang gửi…';try{const data=await api('/v1/quality/report',{method:'POST',body:{type:type.value,message:message.value,question:snapshot}});status.textContent='Đã gửi báo lỗi. Mã: '+data.id;submit.remove();message.disabled=true;type.disabled=true}catch(error){status.textContent=error.message;submit.disabled=false}};d.showModal();
 }
 async function editCache(report,parentStatus){
  const epoch=profileEpoch;
  try{
   const key=report.question.cacheKey,data=await api('/v1/explanations/'+key,{auth:true});if(epoch!==profileEpoch||!moderator)return;const original=data.result.answers[0],d=dialog('Kiểm duyệt giải thích chung',true),form=el('form'),answer=el('input'),reason=el('textarea');answer.value=original.answer;answer.maxLength=8;reason.value=original.explanation;reason.maxLength=3000;reason.rows=5;answer.required=true;reason.required=true;
   form.append(el('p','Giữ nguyên nội dung lựa chọn. Thay đổi được áp dụng cho các lượt học sau; đáp án gốc của bộ đề vẫn được giữ.','muted'),el('pre','Đề: '+report.question.stem),field('Đáp án đề xuất (A, AD, ACE…)',answer),field('Tại sao đúng',reason));
   const rows=original.optionReasons.map(o=>{const input=el('textarea');input.value=o.reason;input.maxLength=1500;input.rows=3;input.required=true;form.append(field(o.id+' — '+o.text,input));return {id:o.id,text:o.text,input}});
   const actions=el('div',undefined,'row'),save=el('button','Lưu bản đã duyệt'),invalidate=el('button','Gỡ giải thích · tạo lại ở lượt sau','secondary'),status=el('p');status.setAttribute('role','status');save.type='submit';invalidate.type='button';actions.append(save,invalidate);form.append(actions,status);d.append(form);
   const send=async action=>{save.disabled=invalidate.disabled=true;try{await api('/v1/explanations/'+key,{method:'PUT',auth:true,body:{action,etag:data.etag,answer:answer.value.trim().toUpperCase(),explanation:reason.value.trim(),optionReasons:rows.map(({input,...o})=>({...o,reason:input.value.trim()}))}});parentStatus.textContent=action==='replace'?'Đã lưu giải thích đã duyệt.':'Đã gỡ giải thích cũ; lượt học sau sẽ tạo lại.';d.close()}catch(error){status.textContent=error.message;save.disabled=invalidate.disabled=false}};
   form.onsubmit=event=>{event.preventDefault();send('replace')};invalidate.onclick=()=>send('invalidate');d.showModal();
  }catch(error){parentStatus.textContent=error.message}
 }
 async function openReview(){
  if(!moderator)return;const d=dialog('Báo lỗi & Chất lượng',true),tabs=el('div',undefined,'row'),reportsButton=el('button','Báo lỗi','secondary'),metricsButton=el('button','Tốc độ & lỗi','secondary'),body=el('div'),status=el('p');status.setAttribute('role','status');tabs.append(reportsButton,metricsButton);d.append(tabs,status,body);d.showModal();
  let cursor=null;
  async function reports(append=false){try{status.textContent='Đang tải…';const data=await api('/v1/quality/reports'+(append&&cursor?'?cursor='+encodeURIComponent(cursor):''),{auth:true});if(!append)body.replaceChildren();cursor=data.cursor;body.querySelector('.quality-more')?.remove();if(!data.reports.length&&!append)body.append(el('p','Chưa có báo lỗi.'));for(const report of data.reports){
   const card=el('article',undefined,'quality-report'),q=report.question;card.append(el('h3',types[report.type]+' · '+({pending:'Chờ duyệt',resolved:'Đã xử lý',rejected:'Không xác nhận'}[report.status])),el('p',new Date(report.createdAt).toLocaleString('vi-VN')),el('p',report.message),el('pre',[q.stem,...q.options.map(o=>o.id+'. '+o.text),'Đáp án đang lưu: '+q.answer,'Giải thích: '+q.explanation].join('\n')));
   if(q.sharedDeck){const image=el('img');image.alt='Ảnh slide được báo lỗi';card.append(image);fetch(new URL('/v1/decks/'+q.sharedDeck+'/images/'+q.sharedIndex,base),{credentials:'omit',signal:AbortSignal.timeout(10000)}).then(async response=>{if(!response.ok)throw Error('Image unavailable');const blob=await response.blob();if(!d.open)return;const url=URL.createObjectURL(blob);image.src=url;d.addEventListener('close',()=>URL.revokeObjectURL(url),{once:true})}).catch(()=>{image.alt='Chưa tải được ảnh gốc từ kho chung.'})}
   const note=el('textarea');note.value=report.reviewNote||'';note.maxLength=2000;note.rows=2;const state=el('select');for(const [id,label]of Object.entries({pending:'Chờ duyệt',resolved:'Đã xử lý',rejected:'Không xác nhận'})){const option=el('option',label);option.value=id;state.append(option)}state.value=report.status;const save=el('button','Lưu xử lý','secondary'),result=el('p');result.setAttribute('role','status');card.append(field('Ghi chú xử lý',note),field('Trạng thái',state),save);
   if(q.cacheKey){const edit=el('button','Xem / sửa giải thích chung','secondary');edit.onclick=()=>editCache(report,result);card.append(edit)}card.append(result);save.onclick=async()=>{save.disabled=true;try{const data=await api('/v1/quality/report',{method:'PUT',auth:true,body:{key:report.key,updatedAt:report.updatedAt,status:state.value,note:note.value}});report.updatedAt=data.report.updatedAt;result.textContent='Đã lưu.'}catch(error){result.textContent=error.message}finally{save.disabled=false}};body.append(card);
  }if(cursor){const more=el('button','Xem báo lỗi cũ hơn','secondary quality-more');more.onclick=()=>reports(true);body.append(more)}status.textContent=''}catch(error){status.textContent=error.message}}
  reportsButton.onclick=()=>reports();metricsButton.onclick=async()=>{try{status.textContent='Đang tải…';const data=await api('/v1/quality/metrics',{auth:true});body.replaceChildren(el('p','Số liệu tổng hợp 14 ngày gần nhất; không chứa đề bài, URL, tài khoản hay nội dung lỗi. Số liệu từ trình duyệt chỉ dùng để tham khảo.','muted'));
   for(const day of data.days){const section=el('article',undefined,'quality-report');section.append(el('h3',day.day));for(const device of ['mobile','desktop']){const get=name=>day.metrics[device+':'+name]||{count:0,total:0,bins:[]},rows=[['Tải ảnh',get('image_ms')],['Chờ AI',get('ai_ms')]],table=el('table');const header=el('tr');for(const title of ['Thiết bị / phép đo','Lượt','Trung bình','P95 (≤)'])header.append(el('th',title));table.append(header);for(const [label,s]of rows){let sum=0,p95='—';for(let i=0;i<s.bins.length;i++){sum+=s.bins[i];if(sum>=s.count*.95&&s.count){p95=[100,500,1000,3000,10000,30000,120000][i]+' ms';break}}const tr=el('tr');for(const value of [device+' · '+label,s.count,s.count?Math.round(s.total/s.count)+' ms':'—',p95])tr.append(el('td',String(value)));table.append(tr)}const hit=get('shared_hit').count,miss=get('shared_miss').count;section.append(table,el('p',device+': dùng lại trên máy '+get('local_hit').count+' lượt; cache chung '+(hit+miss?Math.round(hit/(hit+miss)*100)+'%':'chưa có số liệu')+' ('+hit+'/'+(hit+miss)+'); lỗi ảnh '+get('image_error').count+', AI '+get('ai_error').count+', JavaScript '+(get('js_error').count+get('rejection').count)+'.'))}body.append(section)}if(!data.days.length)body.append(el('p','Chưa có số liệu. Các lượt sử dụng tiếp theo sẽ tự ghi nhận.'));status.textContent='';}catch(error){status.textContent=error.message}};reports();
 }
 const review=el('button','Báo lỗi & Chất lượng','account-menu-item');review.type='button';review.hidden=true;document.querySelector('#accountMenu').append(review);review.onclick=openReview;
 const preparation=el('button','Chuẩn bị giải thích bộ đề','account-menu-item');preparation.id='prepareExplanations';preparation.type='button';preparation.hidden=true;document.querySelector('#accountMenu').append(preparation);
 preparation.onclick=()=>{if(!moderator)return;const epoch=profileEpoch,d=dialog('Chuẩn bị giải thích bộ đề',true),intro=el('p','Máy chủ xử lý từng câu và tự nghỉ khi chạm hạn mức. Đóng tab vẫn tiếp tục. Câu đã có giải thích dùng chung sẽ được bỏ qua.'),list=el('div'),status=el('p'),refresh=el('button','Làm mới tiến độ','secondary');status.setAttribute('role','status');d.append(intro,refresh,status,list);d.showModal();
  async function load(){refresh.disabled=true;try{const {jobs}=await api('/v1/preparation');if(!d.open||epoch!==profileEpoch)return;list.replaceChildren();for(const job of jobs){const card=el('article',undefined,'quality-report');card.append(el('h3',job.title),el('p',`${job.ready||0}/${job.total||0} câu sẵn · đã kiểm tra ${job.cursor||0} · dùng lại ${job.reused||0}`),el('p',`Cần đối chiếu ${job.conflicts||0} · chưa chắc ${job.uncertain||0} · lỗi ${job.failed||0}`));if(job.lastError)card.append(el('p',job.lastError));if(job.status!=='done'){const active=['running','waiting'].includes(job.status),button=el('button',active?'Tạm dừng':'Bắt đầu / Tiếp tục','secondary');button.onclick=async()=>{if(!moderator||epoch!==profileEpoch)return;button.disabled=true;try{await api('/v1/preparation/'+job.id+'/'+(active?'pause':'start'),{method:'POST',auth:true,body:{}});await load()}catch(error){status.textContent=error.message;button.disabled=false}};card.append(button)}else card.append(el('p','Đã kiểm tra hết bộ đề.'));list.append(card)}status.textContent=jobs.length?'':'Chưa có bộ đề trong kho chung.'}catch(error){status.textContent=error.message}finally{refresh.disabled=false}}
  refresh.onclick=load;load();
 };
 async function setProfile(profile){const epoch=++profileEpoch;moderator=false;review.hidden=preparation.hidden=true;for(const dialog of restrictedDialogs)dialog.close();if(!profile||!base)return;try{const result=await api('/v1/quality/access',{auth:true});if(epoch!==profileEpoch)return;moderator=!!result.moderator;review.hidden=preparation.hidden=!moderator}catch{}}
 document.addEventListener('click',event=>{const button=event.target.closest('[data-report-question]');if(button){const q=getQuestion(button.dataset.reportQuestion);if(q)openReport(q)}});
 async function checkFresh(q,details,onStale){
  if(!details?.cacheKey||!details.cacheEtag||!base)return;const id=details.cacheKey+':'+details.cacheEtag,now=Date.now();if(now-(cacheChecked.get(id)||0)<300000)return;cacheChecked.set(id,now);
  try{const data=await api('/v1/explanations/status',{method:'POST',body:{keys:[details.cacheKey]}}),entry=data.entries[details.cacheKey];if(entry&&entry.etag!==details.cacheEtag)onStale(q)}catch{/* Offline study keeps the last locally saved explanation. */}
 }
 return {setProfile,checkFresh,report:openReport};
}
